#!/usr/bin/env python3
"""
Generate the C source defining frozen bootstrap modules for our binary.

CPython's two-phase init imports a few modules — `encodings`, parts of
`importlib` — *before* user code can install meta-path finders. We can't
serve those from our blob via _zippy_finder because the finder isn't on
sys.meta_path yet. Solution: extend `PyImport_FrozenModules` so CPython
finds them via the frozen importer instead.

CPython already pre-freezes a lot (including `importlib._bootstrap`,
`importlib.util`, `importlib.machinery`). What's missing, and what we
add, is `encodings` (so stdout encoding setup works) and `importlib`'s
package marker (CPython freezes its submodules but not the parent
package, so `import importlib.machinery` fails with sys.path empty).

The output C file:
  - Embeds each chosen module's marshalled bytecode as a static byte array.
  - Exposes install_frozen_bootstrap() which prepends our table to
    PyImport_FrozenModules at startup.

<python_root> is the self-built CPython install prefix (bin/, lib/, include/).

Usage: gen_frozen_bootstrap.py <python_root> <out.c>
"""

import marshal
import os
import sys

# Modules to add to the frozen table. Order matters within a package: the
# parent package must come before its children.
BOOTSTRAP = [
    # encodings — CPython needs these set up before any I/O or print().
    ("encodings", True),
    ("encodings.aliases", False),
    ("encodings.utf_8", False),
    ("encodings.latin_1", False),
    ("encodings.ascii", False),
    # importlib package marker. CPython pre-freezes the internal
    # importlib bits but not the parent package, so `import
    # importlib.machinery` fails when sys.path is empty.
    ("importlib", True),
]

# encodings/__init__.py registers a code-page codec search function on
# Windows, so importing the package there pulls in this module before any
# path-based finder exists.
if sys.platform == "win32":
    BOOTSTRAP.append(("encodings._win_cp_codecs", False))


def find_stdlib_root(python_root: str) -> str:
    """Locate the standard library inside a self-built CPython prefix.

    A candidate has to contain os.py: on Windows the prefix also holds a
    lib/python3.x directory, but it carries only the generated inittab
    source because CPython's Windows path resolution requires the real
    stdlib to sit in a Lib directory beside the executable.
    """
    candidates = [os.path.join(python_root, "bin", "Lib")]
    lib_dir = os.path.join(python_root, "lib")
    if os.path.isdir(lib_dir):
        candidates.extend(
            os.path.join(lib_dir, dirname)
            for dirname in sorted(os.listdir(lib_dir))
            if dirname.startswith("python3.")
        )
    for candidate in candidates:
        if os.path.isfile(os.path.join(candidate, "os.py")):
            return candidate
    raise SystemExit(f"stdlib directory not found near {python_root}")


def find_module_path(stdlib_root: str, dotted: str) -> str:
    rel = dotted.replace(".", "/")
    candidates = [
        os.path.join(stdlib_root, rel + ".py"),
        os.path.join(stdlib_root, rel, "__init__.py"),
    ]
    for c in candidates:
        if os.path.isfile(c):
            return c
    raise SystemExit(f"could not find {dotted} in {stdlib_root}")


def emit_byte_array(name: str, data: bytes) -> str:
    lines = [f"static const unsigned char {name}[] = {{"]
    rows = []
    for i in range(0, len(data), 16):
        rows.append("    " + ", ".join(f"0x{b:02x}" for b in data[i : i + 16]))
    lines.append(",\n".join(rows))
    lines.append("};")
    return "\n".join(lines)


def main() -> None:
    if len(sys.argv) != 3:
        print(__doc__, file=sys.stderr)
        sys.exit(1)
    python_root, out_c = sys.argv[1], sys.argv[2]
    stdlib = find_stdlib_root(python_root)

    pieces: list[str] = [
        "// Generated by gen_frozen_bootstrap.py — do not edit.",
        "#define PY_SSIZE_T_CLEAN",
        "#include <Python.h>",
        "",
    ]

    array_names: list[
        tuple[str, str, int, bool]
    ] = []  # (dotted, sym, n, is_pkg)
    for dotted, is_pkg in BOOTSTRAP:
        path = find_module_path(stdlib, dotted)
        with open(path, "rb") as f:
            src = f.read()
        try:
            filename = os.path.relpath(path, stdlib).replace(os.sep, "/")
            code = compile(
                src, filename, "exec", dont_inherit=True, optimize=2
            )
        except SyntaxError as e:
            raise SystemExit(f"compile failed for {dotted}: {e}")
        data = marshal.dumps(code)
        sym = "frozen_" + dotted.replace(".", "_")
        array_names.append((dotted, sym, len(data), is_pkg))
        pieces.append(emit_byte_array(sym, data))
        pieces.append("")

    pieces.append("static const struct _frozen frozen_table[] = {")
    for dotted, sym, n, is_pkg in array_names:
        pieces.append(f'    {{"{dotted}", {sym}, {n}, {1 if is_pkg else 0}}},')
    pieces.append("    {NULL, NULL, 0, 0},")
    pieces.append("};")
    pieces.append("")
    pieces.append(
        "// Called from main() before Py_InitializeFromConfig.\n"
        "// Replaces PyImport_FrozenModules with our extended table.\n"
        "static struct _frozen extended_frozen[256];\n"
        "\n"
        "void install_frozen_bootstrap(void) {\n"
        "    extern const struct _frozen *PyImport_FrozenModules;\n"
        "    const struct _frozen *orig = PyImport_FrozenModules;\n"
        "    int n = 0;\n"
        "    int cap = (int)(sizeof(extended_frozen) / "
        "sizeof(extended_frozen[0])) - 1;\n"
        "    if (orig) {\n"
        "        while (orig[n].name && n < cap) {\n"
        "            extended_frozen[n] = orig[n];\n"
        "            n++;\n"
        "        }\n"
        "    }\n"
        "    for (int i = 0; frozen_table[i].name; i++) {\n"
        "        if (n >= cap) break;\n"
        "        extended_frozen[n++] = frozen_table[i];\n"
        "    }\n"
        "    extended_frozen[n].name = NULL;\n"
        "    PyImport_FrozenModules = extended_frozen;\n"
        "}"
    )

    with open(out_c, "w") as f:
        f.write("\n".join(pieces))
        f.write("\n")
    print(f"wrote {out_c}: {len(array_names)} frozen modules", file=sys.stderr)


if __name__ == "__main__":
    main()
